'use strict';
// Terrain uses one fixed presentation; remove the inherited detail chooser.
$('layers').onclick=null;$('layers').remove();
const initialParams=new URLSearchParams(location.search);
let terrainConfig=ProceduralRanch.normalize({...TerrainPresets.get(initialParams.get('preset'))?.parameters,...Object.fromEntries(initialParams)}),terrainMessage='';
let terrainSeed=(Number(new URLSearchParams(location.search).get('seed'))>>>0)||41,bareWorld,busy=false;
// Use the existing ink assets and contour engine, with all geometry supplied by the seed.
renderSite=function(){
 artDefs();el('rect',{x:-1000,y:-1000,width:2000,height:2000,fill:'#f8f5e9'});poly([[0,0],[180,0],[180,180],[0,180]],'#dce1bd','none');
 const brook=world.water.brook,shore=world.water.shoreline,riverLine=shore?brook.centerline.filter(p=>p[0]<=shore[Math.max(0,Math.min(144,Math.round(p[1]/1.25)))][0]):brook.centerline,d=flowingPath(riverLine);el('path',{d,fill:'none',stroke:'#7f9f75','stroke-width':brook.width+1.9,'stroke-linecap':'round'});editableTerrainArtwork();zoneSurfaceArtwork();
 el('path',{d,fill:'none',stroke:'#b5cfc3','stroke-width':brook.width,'stroke-linecap':'round'});el('path',{d,fill:'none',stroke:'#dbe6d4','stroke-width':brook.width*.49,opacity:.6,'stroke-linecap':'round'});
 const rand=inkRandom(world.seed);for(let i=0;i<150;i++){const x=24+rand()*132,y=10+rand()*150,surface=world.terrain.surfaceGrid?.values[Math.round(y/world.terrain.grid.spacing)]?.[Math.round(x/world.terrain.grid.spacing)];if(surface&&!['meadow','woodland'].includes(surface))continue;if(world.placement?.some(b=>x>b.x-2&&x<b.x+b.w+2&&y>b.y-2&&y<b.y+b.h+2))continue;inkPath(`M${x},${-y}q.3,-1 .5,-.2m.3,.4q.4,-.8 .5,-.5`,{stroke:'#82916a','stroke-width':.15,opacity:.7});}
 for(const p of world.parcels.filter(p=>p.fenced)){poly(p.polygon,'#c4ce9d55','none');const a=[...p.polygon,p.polygon[0]];line(a,'#777b59',.36);for(let i=0;i<4;i++){const u=a[i],v=a[i+1],n=Math.ceil(Math.hypot(v[0]-u[0],v[1]-u[1])/3);for(let j=0;j<n;j++){let x=u[0]+(v[0]-u[0])*j/n,y=u[1]+(v[1]-u[1])*j/n;line([[x,y-.7],[x,y+.7]],'#686d50',.26);}}}
 for(const p of world.paths){for(const [color,width] of [['#a4ab87',p.width+1],['#eadbb6',p.width]])line(p.points,color,width);}
 for(const o of world.outdoorContents){const [x,y]=o.position,[w,h]=o.size;poly([[x,y],[x+w,y],[x+w,y+h],[x,y+h]],'#b3a27b','#8d8b66',.15);for(let a=0;a<5;a++)for(let b=0;b<2;b++)el('circle',{cx:x+.7+a,cy:-y-.7-b,r:.29,fill:rand()>.3?'#7d9864':'#c5ad70'});}
 for(const t of [...world.vegetation].sort((a,b)=>b.position[1]-a.position[1]))tree(t);for(const b of world.buildings)roof(b);
 if(world.grown){const g=world.parcels.find(p=>p.id==='vegetables'),c=center(g.polygon);txt(c[0],c[1]+10,'KITCHEN GARDEN',2,svg,{class:'label'});}
 svg.classList.add('pen-wash');$('scale').textContent='CONTOURS '+contourStep()+' m · NORTH UP';
};
function present(refit=true){building=null;$('land').classList.add('active');$('rooms').classList.remove('active');$('back').hidden=true;render();if(refit)fit();$('eyebrow').textContent='RANCH ATELIER · GENERATOR';$('scene-title').textContent='Terrain Generator';$('hint').textContent=(TerrainPresets.zones.find(z=>z.id===world.biome)?.name||'Meadow & brook')+' · 180 × 180 metres';$('seed-label').textContent='LANDSCAPE '+terrainSeed;$('growth-state').textContent=world.grown?'Ranch grown · 4 connected places':'Terrain ready · seed retained';$('grow-ranch').disabled=world.grown||busy;$('grow-ranch').textContent=world.grown?'Ranch grown ✓':'Grow the ranch';$('reset-land').hidden=!world.grown;updateTerrainSummary();window.RanchView?.changed();}
site=()=>present();$('land').onclick=site;$('back').onclick=site;
function saveTerrainURL(){const q=new URLSearchParams({seed:String(terrainSeed)});const preset=TerrainPresets.match(terrainConfig);if(preset){q.set('preset',preset.id);q.set('presetVersion',preset.version);}for(const [k,v]of Object.entries(terrainConfig))q.set(k,v);if(world.grown)q.set('grown','1');history.replaceState(null,'',location.pathname+'?'+q);}
function newLandscape(seed,refit=true){terrainSeed=seed;bareWorld=ProceduralRanch.landscape(seed,terrainConfig);terrainConfig={...bareWorld.config};world=bareWorld;saveTerrainURL();present(refit);}
$('new-land').onclick=()=>{if(!busy){terrainMessage='New seed; terrain settings retained.';newLandscape((terrainSeed+1)>>>0||1,false);syncTerrainInputs();}};
$('grow-ranch').onclick=async()=>{if(busy||world.grown)return;setTerrainBusy(true);$('growth-state').textContent='Finding dry ground and connecting paths…';await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));try{world=ProceduralRanch.grow(bareWorld);terrainMessage='Ranch placed on this terrain.';saveTerrainURL();}catch(e){terrainMessage=e.message;}finally{setTerrainBusy(false);present(false);}};
$('reset-land').onclick=()=>{world=bareWorld;terrainMessage='Ranch removed; terrain retained.';saveTerrainURL();present(false)};
notes=function(){const p=open('Meadow, woodland & brook','TERRAIN GENERATOR');html('p','The seed and all terrain settings are saved in this page’s address. Copy the link to return to exactly this landscape.',p);card(p,'Shape the ground','Broad valley relief, directional hills, meadow flattening and fine roughness are separate controls. The brook cuts into the elevation surface. This is a designed height field, not an erosion or flood simulation.');card(p,'Grow on the terrain','Ranch sites are checked against the edited ground and brook clearance. Steep or narrow landscapes may not fit a complete ranch.');const a=html('button','Download this world',p,'action');a.onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(world,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='ranch-'+terrainSeed+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};};
$('journal').onclick=notes;$('about').onclick=notes;$('rooms').onclick=()=>{if(world.grown)buildingsPanel();else{const p=open('First, grow a ranch','THE CLEARING');html('p','Grow the ranch to add a farmhouse and barn with simple schematic interiors.',p)}};
function contourStep(){return world.terrain.stats.range>16?2:world.terrain.stats.range>8?1:.5;}
function editableTerrainArtwork(){
 const grid=world.terrain.grid,h=grid.heights,step=grid.spacing,interval=contourStep(),lo=Math.floor(world.terrain.stats.minimum/interval)*interval,hi=world.terrain.stats.maximum;
 const g=el('g',{'pointer-events':'none','aria-hidden':'true',id:'terrain-topography'}),bands=new Map(),lines=new Map(),colors=['#91ab86','#a7b78e','#b9c399','#c9cba3','#d5d0ae','#e0d6ba','#e9dfca'];
 for(let j=0;j<grid.rows-1;j++)for(let i=0;i<grid.cols-1;i++){const p=(dx,dy)=>[(i+dx)*step,(j+dy)*step,h[j+dy][i+dx]],a=p(0,0),b=p(1,0),c=p(1,1),d=p(0,1);for(const tri of [[a,b,c],[a,c,d]]){
  const min=Math.min(...tri.map(p=>p[2])),max=Math.max(...tri.map(p=>p[2]));
  for(let z=Math.floor(min/interval)*interval;z<=max;z+=interval){const region=clipHeight(clipHeight(tri,z,true),z+interval,false);if(region.length>=3){const path='M'+region.map(p=>p[0].toFixed(2)+','+(-p[1]).toFixed(2)).join('L')+'Z';bands.set(z,(bands.get(z)||'')+path);}}
  for(let z=Math.ceil(min/interval)*interval;z<max;z+=interval){const hits=[];for(let k=0;k<3;k++){const u=tri[k],v=tri[(k+1)%3];if((u[2]<=z&&v[2]>z)||(v[2]<=z&&u[2]>z)){const t=(z-u[2])/(v[2]-u[2]);hits.push([u[0]+t*(v[0]-u[0]),u[1]+t*(v[1]-u[1])]);}}if(hits.length===2)lines.set(z,(lines.get(z)||'')+`M${hits[0][0].toFixed(2)},${-hits[0][1].toFixed(2)}L${hits[1][0].toFixed(2)},${-hits[1][1].toFixed(2)}`);}
 }}
 for(const [z,d]of bands)el('path',{d,fill:colors[Math.min(6,Math.floor((z-lo)/Math.max(1,hi-lo)*7))],opacity:.55},g);
 for(const [z,d]of lines)el('path',{d,fill:'none',stroke:'#647958','stroke-width':Number.isInteger(z)? .22:.12,opacity:.48},g);
}
const controlGroups=[
 ['Landform', [['relief','Valley relief','m',.5],['hillHeight','Hill height','m',.2],['hillScale','Hill size','m',5],['ridgeAngle','Ridge direction','°',5],['valleyWidth','Valley width','m',1],['flatGround','Meadow flattening','%',5],['roughness','Fine roughness','m',.05]]],
 ['Brook', [['streamWidth','Width','m',.1],['streamDepth','Depth','m',.1],['streamBends','Bend amount','×',.1],['streamPosition','Northward position','m',1]]],
 ['Woodland', [['woodland','Woodland density','%',5],['clustering','Clustering','%',5],['clearing','Clearing size','%',5],['setback','Tree setback from bank','m',1]]]
];
const terrainPanel=document.createElement('section');terrainPanel.className='controls terrain-controls';terrainPanel.setAttribute('aria-label','Terrain editor');
terrainPanel.innerHTML='<h2>Shape the terrain</h2><p class="terrain-description">Fine-tune the selected zone. Keep the seed to compare one change at a time.</p><label class="terrain-seed" for="terrain-seed">Landscape seed <input id="terrain-seed" type="number" min="1" max="4294967295" step="1"></label>'+controlGroups.map(([title,items])=>'<details '+(title==='Landform'?'open':'')+'><summary>'+title+'</summary>'+items.map(([key,label,unit,step])=>{const [,min,max]=ProceduralRanch.settings[key];return '<label class="terrain-field" for="terrain-'+key+'"><span>'+label+'</span><output id="value-'+key+'"></output><input id="terrain-'+key+'" data-terrain="'+key+'" type="range" min="'+min+'" max="'+max+'" step="'+step+'" data-unit="'+unit+'"></label>'}).join('')+'</details>').join('')+'<label class="terrain-resolution" for="terrain-spacing">Terrain sampling<select id="terrain-spacing"><option value="5">5 m · quick</option><option value="2.5">2.5 m · detailed</option><option value="1.25">1.25 m · fine</option></select></label><p class="terrain-description">Applying edits removes the ranch so you can grow it again on the new ground.</p><div class="terrain-actions"><button id="terrain-apply">Apply terrain</button><button id="terrain-defaults">Reset settings</button></div><button id="terrain-copy">Copy landscape link</button><p id="terrain-feedback" role="status"></p><p id="terrain-summary"></p>';
const presetPanel=document.createElement('section');presetPanel.className='terrain-presets';presetPanel.setAttribute('aria-label','Terrain presets');
presetPanel.innerHTML='<label class="terrain-resolution" for="terrain-zone">Terrain zone<select id="terrain-zone">'+TerrainPresets.zones.map(z=>'<option value="'+z.id+'">'+z.name+'</option>').join('')+'</select></label><p id="terrain-zone-description" class="terrain-description"></p><h2>Terrain presets</h2><p class="terrain-description">Five landforms for the selected zone. Replace terrain and ranch while keeping your seed. Previews show meadow versions.</p><div class="terrain-preset-list">'+TerrainPresets.presets.map(p=>'<button class="terrain-preset" data-preset="'+p.id+'" aria-pressed="false"><span class="terrain-preset-preview" aria-hidden="true">'+presetThumbnail(p)+'</span><span><strong>'+p.name+'</strong><small>'+p.description+'</small></span></button>').join('')+'</div>';
terrainPanel.prepend(presetPanel);
const exportPanel=document.createElement('details');exportPanel.className='terrain-exports';exportPanel.innerHTML='<summary>Reuse this terrain</summary><p class="terrain-description">Save the full recipe, or export a 100 m hex cut from its centre for the tile composer. Tile export includes heights and candidate ground; neighboring edges still need matching.</p><button id="terrain-export-recipe">Download terrain recipe</button><button id="terrain-export-tile">Download tile terrain</button>';
terrainPanel.append(exportPanel);$('stage').append(terrainPanel);
function presetThumbnail(p){const w=ProceduralRanch.landscape(41,{...p.parameters,spacing:5}),g=w.terrain.grid,lo=w.terrain.stats.minimum,range=w.terrain.stats.range,colors=['#a6bf9f','#b7c79d','#c7cea7','#d4d4b3','#dedcc4'];let marks='';for(let j=0;j<36;j+=2)for(let i=0;i<36;i+=2){const z=g.heights[j][i],color=colors[Math.min(4,Math.floor((z-lo)/range*5))];marks+='<rect x="'+i*5+'" y="'+(170-j*5)+'" width="10.5" height="10.5" fill="'+color+'"/>';}marks+='<polyline points="'+w.water.brook.centerline.map(p=>p[0]+','+(180-p[1])).join(' ')+'" fill="none" stroke="#7caaa5" stroke-width="'+w.water.brook.width+'"/>';for(const t of w.vegetation)marks+='<circle cx="'+t.position[0]+'" cy="'+(180-t.position[1])+'" r="'+t.radius+'" fill="#66845e" opacity=".7"/>';return '<svg viewBox="0 0 180 180" xmlns="http://www.w3.org/2000/svg">'+marks+'</svg>';}
function downloadTerrain(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
for(const button of presetPanel.querySelectorAll('[data-preset]'))button.onclick=async()=>{if(busy)return;const seed=Number($('terrain-seed').value),p=TerrainPresets.get(button.dataset.preset);if(!Number.isInteger(seed)||seed<1||seed>4294967295){terrainMessage='Enter a valid landscape seed first.';updateTerrainSummary();return;}setTerrainBusy(true);$('terrain-feedback').textContent='Shaping '+p.name+'…';await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));try{terrainConfig={...p.parameters,biome:terrainConfig.biome,spacing:terrainConfig.spacing};terrainMessage=p.name+' applied · seed '+seed+' retained.';newLandscape(seed,false);syncTerrainInputs();}finally{setTerrainBusy(false);updateTerrainSummary();}};
$('terrain-export-recipe').onclick=()=>{const preset=TerrainPresets.match(terrainConfig);downloadTerrain({schema:'ranch-atelier/terrain-recipe',schemaVersion:TerrainPresets.version,generatorVersion:'terrain-heightfield/1.0.0',prefabId:preset?.id||'custom',prefabVersion:TerrainPresets.version,seed:terrainSeed,parameters:terrainConfig},'terrain-'+(preset?.id||'custom')+'-'+terrainSeed+'.json');};
$('terrain-export-tile').onclick=()=>{downloadTerrain(TerrainPresets.provider(bareWorld),'terrain-tile-'+terrainSeed+'.json');terrainMessage='100 m hex terrain exported. Neighbor compatibility still needs checking.';updateTerrainSummary();};
function updateOutput(input){$('value-'+input.dataset.terrain).textContent=Number(input.value)+' '+input.dataset.unit;}
function syncTerrainInputs(){$('terrain-seed').value=terrainSeed;for(const input of terrainPanel.querySelectorAll('[data-terrain]')){input.value=terrainConfig[input.dataset.terrain];updateOutput(input);}$('terrain-spacing').value=terrainConfig.spacing;$('terrain-zone').value=terrainConfig.biome;$('terrain-zone-description').textContent=TerrainPresets.zones.find(z=>z.id===terrainConfig.biome)?.description||'';const selected=TerrainPresets.match(terrainConfig);for(const button of presetPanel.querySelectorAll('[data-preset]'))button.setAttribute('aria-pressed',String(button.dataset.preset===selected?.id));}
function updateTerrainSummary(){if(!$('terrain-summary'))return;const stats=world.terrain.stats;$('terrain-feedback').textContent=terrainMessage;$('terrain-summary').textContent=`${stats.range.toFixed(1)} m elevation range · ${world.vegetation.length} trees · ${world.terrain.grid.cols} × ${world.terrain.grid.rows} samples`;}
function setTerrainBusy(value){busy=value;for(const b of terrainPanel.querySelectorAll('button,input,select'))b.disabled=value;$('new-land').disabled=value;$('grow-ranch').disabled=value||world.grown;window.RanchView?.changed();}
async function applyTerrain(reset=false){if(busy)return;const seed=Number($('terrain-seed').value);if(!Number.isInteger(seed)||seed<1||seed>4294967295){terrainMessage='Enter a whole seed from 1 to 4294967295.';updateTerrainSummary();return;}const next=reset?{...ProceduralRanch.defaults}:Object.fromEntries([...terrainPanel.querySelectorAll('[data-terrain]')].map(i=>[i.dataset.terrain,Number(i.value)]));if(!reset){next.spacing=Number($('terrain-spacing').value);next.biome=terrainConfig.biome;}setTerrainBusy(true);$('terrain-feedback').textContent='Shaping terrain…';await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));try{terrainConfig=ProceduralRanch.normalize(next);terrainMessage=reset?'Default terrain settings restored; seed retained.':'Terrain updated; seed '+seed+' retained.';newLandscape(seed,false);syncTerrainInputs();}catch(e){terrainMessage=e.message;}finally{setTerrainBusy(false);updateTerrainSummary();}}
for(const input of terrainPanel.querySelectorAll('[data-terrain]'))input.oninput=()=>{updateOutput(input);terrainMessage='Unapplied changes. Apply terrain to update the map.';updateTerrainSummary();window.RanchView?.changed();};
$('terrain-spacing').onchange=$('terrain-seed').oninput=()=>{terrainMessage='Unapplied changes. Apply terrain to update the map.';updateTerrainSummary();};
$('terrain-apply').onclick=()=>applyTerrain();$('terrain-defaults').onclick=()=>applyTerrain(true);
$('terrain-copy').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);terrainMessage='Landscape link copied (applied settings).';}catch{terrainMessage='Copy the page address to save the applied landscape.';}updateTerrainSummary();};
$('terrain-zone').onchange=async()=>{if(busy)return;const zone=TerrainPresets.zones.find(z=>z.id===$('terrain-zone').value);setTerrainBusy(true);$('terrain-feedback').textContent='Shaping '+zone.name+'…';await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));try{terrainConfig={...TerrainPresets.get(zone.preset).parameters,biome:zone.id,spacing:terrainConfig.spacing};terrainMessage=zone.name+' generated; seed '+terrainSeed+' retained.';newLandscape(terrainSeed,false);syncTerrainInputs();}finally{setTerrainBusy(false);updateTerrainSummary();}};
function zoneSurfaceArtwork(){
 if(!['wetland','rocky-foothills','coast-estuary'].includes(world.biome))return;
 const g=world.terrain.grid,types=world.terrain.surfaceGrid.values,paths=new Map(),colors={'freshwater':'#9abdb2','saltwater':'#91b3b5','brackish-water':'#9cbab0','wet-ground':'#91a783','sand':'#dfd2a7','rock':'#aaa89a'},step=g.spacing;
 const height=g.heights,level=world.water.level,layers=world.biome==='wetland'?[['wet-ground',level+.55],['freshwater',level]]:world.biome==='coast-estuary'?[['sand',level+.6],['saltwater',level]]:[['rock',null]];
 for(let j=0;j<g.rows-1;j++)for(let i=0;i<g.cols-1;i++)for(const [type,threshold]of layers){
  const point=(dx,dy)=>[(i+dx)*step,(j+dy)*step,threshold===null?(types[j+dy][i+dx]===type?0:1):height[j+dy][i+dx]],a=point(0,0),b=point(1,0),c=point(1,1),d=point(0,1);
  for(const tri of [[a,b,c],[a,c,d]]){const poly=clipHeight(tri,threshold===null?.5:threshold,false);if(poly.length>=3)paths.set(type,(paths.get(type)||'')+'M'+poly.map(p=>p[0].toFixed(2)+','+(-p[1]).toFixed(2)).join('L')+'Z');}
 }
 for(const [type,d]of paths)el('path',{d,fill:colors[type],opacity:type==='rock'?.65:.85,'pointer-events':'none'});
 const random=inkRandom(world.seed+257);for(let i=0;i<200;i++){const x=random()*180,y=random()*180,type=types[Math.min(g.rows-1,Math.floor(y/step))][Math.min(g.cols-1,Math.floor(x/step))];if(type==='rock')inkPath(`M${x},${-y}l1,-.8 1.3,.3m-1.3,-.3l.3,1.1`,{stroke:'#767c71','stroke-width':.18,opacity:.6});if(type==='wet-ground')inkPath(`M${x},${-y}l-.3,-1.2m.3,1.2l.5,-1.6m-.5,1.6l1,-.8`,{stroke:'#617e62','stroke-width':.18,opacity:.6});}
}
const restoreGrown=initialParams.get('grown')==='1';newLandscape(terrainSeed);syncTerrainInputs();if(restoreGrown){try{world=ProceduralRanch.grow(bareWorld);saveTerrainURL();present();}catch(e){terrainMessage=e.message;present();}}
window.RanchView?.register('terrainEditor',()=>({seed:terrainSeed,preset:TerrainPresets.match(terrainConfig)?.id||'custom',presetVersion:TerrainPresets.version,config:terrainConfig,biome:world.biome,busy,grown:world.grown,stats:world.terrain.stats,trees:world.vegetation.length,gridSpacing:world.terrain.grid.spacing,message:terrainMessage,draft:Object.fromEntries([...terrainPanel.querySelectorAll('[data-terrain]')].map(i=>[i.dataset.terrain,Number(i.value)])),view,selectedBuilding:building?.id||null}));
